CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL,
 handle text NOT NULL UNIQUE CHECK (handle ~ '^[a-z0-9_]{3,32}$'), display_name text NOT NULL,
 visibility text NOT NULL DEFAULT 'hidden' CHECK(visibility IN ('public','hidden')),
 biography text NOT NULL DEFAULT '', avatar_id uuid, cover_id uuid,
 game jsonb NOT NULL DEFAULT '{}', online_opt_in boolean NOT NULL DEFAULT false,
 platform_role text NOT NULL DEFAULT 'member' CHECK(platform_role IN ('member','moderator','admin')),
 status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')),
 verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 last_seen timestamptz, deleted_at timestamptz, version integer NOT NULL DEFAULT 1
);
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,csrf_token text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz,last_seen timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL CHECK(purpose IN ('verify','reset')),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE blocks(blocker_id uuid NOT NULL REFERENCES users(id),blocked_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));
CREATE TABLE follows(follower_id uuid NOT NULL REFERENCES users(id),followee_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(follower_id,followee_id),CHECK(follower_id<>followee_id));
CREATE TABLE clubs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,description text NOT NULL,join_mode text NOT NULL CHECK(join_mode IN ('open','approval')),feed_visibility text NOT NULL CHECK(feed_visibility IN ('public','members_only')),avatar_id uuid,cover_id uuid,rules text NOT NULL DEFAULT '',event_roles jsonb NOT NULL DEFAULT '["owner","admin","moderator"]',state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','archived','deleted')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,pinned_post_id uuid);
CREATE INDEX clubs_owner_idx ON clubs(owner_id);
CREATE TABLE club_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES clubs(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','admin','moderator','member')),state text NOT NULL CHECK(state IN ('pending','active','rejected','left','kicked')),nickname text NOT NULL,nickname_key text NOT NULL,avatar_id uuid,roles jsonb NOT NULL DEFAULT '[]',consent_version integer,consented_at timestamptz,revoked_at timestamptz,reason text,joined_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(club_id,user_id));
CREATE UNIQUE INDEX club_nickname_active_idx ON club_memberships(club_id,nickname_key) WHERE state IN ('pending','active');
CREATE TABLE club_name_reservations(club_id uuid NOT NULL REFERENCES clubs(id),nickname_key text NOT NULL,user_id uuid NOT NULL REFERENCES users(id),PRIMARY KEY(club_id,nickname_key));
CREATE TABLE club_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES clubs(id),from_id uuid NOT NULL REFERENCES users(id),to_id uuid NOT NULL REFERENCES users(id),state text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid NOT NULL REFERENCES users(id),club_id uuid REFERENCES clubs(id),state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','pending','published','rejected','removed')),audience text NOT NULL DEFAULT 'public' CHECK(audience IN ('public','members_only')),current_revision_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE post_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid NOT NULL REFERENCES posts(id),body text NOT NULL CHECK(char_length(body)<=5000),images jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_array_length(images)<=4),tags jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'pending' CHECK(status IN ('draft','pending','approved','rejected')),reviewer_id uuid REFERENCES users(id),reason text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
ALTER TABLE posts ADD CONSTRAINT posts_revision_fk FOREIGN KEY(current_revision_id) REFERENCES post_revisions(id);
ALTER TABLE clubs ADD CONSTRAINT clubs_pin_fk FOREIGN KEY(pinned_post_id) REFERENCES posts(id);
CREATE INDEX posts_feed_idx ON posts(created_at DESC,id) WHERE state='published';
CREATE TABLE comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid NOT NULL REFERENCES posts(id),parent_id uuid REFERENCES comments(id),author_id uuid REFERENCES users(id),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 5000),state text NOT NULL DEFAULT 'published' CHECK(state IN ('published','removed')),snapshot_nickname text,snapshot_avatar_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX comments_post_idx ON comments(post_id,created_at,id);
CREATE TABLE reactions(user_id uuid NOT NULL REFERENCES users(id),post_id uuid NOT NULL REFERENCES posts(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,post_id));
CREATE TABLE bookmarks(user_id uuid NOT NULL REFERENCES users(id),post_id uuid NOT NULL REFERENCES posts(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,post_id));
CREATE TABLE mentions(post_id uuid NOT NULL REFERENCES posts(id),user_id uuid NOT NULL REFERENCES users(id),PRIMARY KEY(post_id,user_id));
CREATE TABLE lfg_announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid NOT NULL REFERENCES users(id),server text NOT NULL,roles jsonb NOT NULL,description text NOT NULL,expires_at timestamptz NOT NULL,pending_policy text NOT NULL CHECK(pending_policy IN ('keep','reject')),state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed','expired','deleted')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lfg_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),announcement_id uuid NOT NULL REFERENCES lfg_announcements(id),applicant_id uuid NOT NULL REFERENCES users(id),message text NOT NULL,disclosure_consent boolean NOT NULL DEFAULT false,disclosed_nickname text,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','rejected','cancelled','auto_rejected')),created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,UNIQUE(announcement_id,applicant_id));
CREATE TABLE lfg_contacts(application_id uuid NOT NULL REFERENCES lfg_applications(id),user_id uuid NOT NULL REFERENCES users(id),contact_encrypted text NOT NULL,consented_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,PRIMARY KEY(application_id,user_id));
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES clubs(id),creator_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,description text NOT NULL,audience text NOT NULL CHECK(audience IN ('public','members_only')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,registration_closes_at timestamptz NOT NULL,capacity integer NOT NULL CHECK(capacity>0),state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','cancelled','completed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),CHECK(registration_closes_at<=starts_at));
CREATE TABLE event_registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),user_id uuid NOT NULL REFERENCES users(id),state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,user_id));
CREATE TABLE notification_preferences(user_id uuid NOT NULL REFERENCES users(id),event_type text NOT NULL,enabled boolean NOT NULL,PRIMARY KEY(user_id,event_type));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES users(id),event_type text NOT NULL,object_type text NOT NULL,object_id uuid NOT NULL,actor_id uuid REFERENCES users(id),dedupe_key text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz);
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type text NOT NULL,payload jsonb NOT NULL,available_at timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0,completed_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox(available_at) WHERE completed_at IS NULL;
CREATE TABLE media_blobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),storage_key text NOT NULL UNIQUE,mime text NOT NULL,size_bytes integer NOT NULL,sha256 text NOT NULL,state text NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','deleted')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES users(id),target_type text NOT NULL CHECK(target_type IN ('profile','post','comment','club','lfg','event')),target_id uuid NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','reviewing','resolved','dismissed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES users(id),target_type text NOT NULL,target_id uuid NOT NULL,action text NOT NULL,reason text NOT NULL,report_id uuid REFERENCES reports(id),created_at timestamptz NOT NULL DEFAULT now(),metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE sanctions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),actor_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('warning','suspension')),reason text NOT NULL,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE TABLE audit_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),club_id uuid REFERENCES clubs(id),action text NOT NULL,target_id uuid,reason text NOT NULL DEFAULT '',metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys(user_id uuid NOT NULL REFERENCES users(id),key text NOT NULL,operation text NOT NULL,response jsonb NOT NULL,request_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key,operation));
